                id: typeof item.id === 'string' && item.id !== '' ? item.id : makeId('d'),
                title: item.title.trim(),
                status: statuses.includes(item.status) ? item.status : 'open',
                caseId: typeof item.caseId === 'string' ? item.caseId : '',
