    status.cases = cases.length === 0 ? 'todo' : casesReady ? 'done' : 'doing';
    // ③ Run: the model's turn; complete once every case has a verdict.
    status.execution = cases.length === 0 || ranCases === 0 ? 'todo' : ranCases === cases.length ? 'done' : 'doing';
